package pesto

import (
	"os"
	"sync"
	"testing"
)

// Run is the entry point that generated test wrappers call. It builds a [T] wired
// to the environment selected by `pesto run` and invokes the authored test body.
//
//	// generated by pesto run:
//	func TestCreateUser(t *testing.T) { pesto.Run(t, pestoBody_TestCreateUser) }
//
// The environment is resolved once per test binary from the PESTO_ENV and
// PESTO_ROOT variables that `pesto run` sets. When PESTO_ENV is unset (for example
// a plain `go test` with no transform), Run builds a [T] with no environment,
// which is still valid for tests that configure their client explicitly.
func Run(t *testing.T, body func(*T), opts ...Option) {
	t.Helper()
	pt := New(t, append(runEnvironmentOptions(t), opts...)...)
	body(pt)
}

var (
	runEnvOnce sync.Once
	runEnv     *Environment
	runEnvErr  error
)

// runEnvironmentOptions loads the selected environment once per binary and returns
// it as options. It is a no-op unless PESTO_ENV is set.
func runEnvironmentOptions(t *testing.T) []Option {
	t.Helper()

	name := os.Getenv("PESTO_ENV")
	if name == "" {
		return nil
	}

	runEnvOnce.Do(func() {
		root := os.Getenv("PESTO_ROOT")
		if root == "" {
			root = "."
		}
		runEnv, runEnvErr = LoadEnvironment(root, name)
	})

	if runEnvErr != nil {
		t.Fatalf("pesto: load environment %q: %v", name, runEnvErr)
	}
	if runEnv == nil {
		return nil
	}
	return []Option{WithEnvironment(runEnv)}
}
